export const getDeleteInvestmentTransactionUrl = (id: string) => {
  return `/api/investments/transactions/${id}`;
};

/**
 * Removes the entry and its cash effect. A later broker import will not bring a deleted imported entry back.
 * @summary Delete an investment transaction
 */
export const deleteInvestmentTransaction = async (
  id: string,
  options?: Parameters<typeof customFetch>[1],
): Promise<void> => {
  return customFetch<void>(getDeleteInvestmentTransactionUrl(id), {
    ...options,
    method: "DELETE",
  });
};

export const getDeleteInvestmentTransactionMutationKey = () =>
  ["deleteInvestmentTransaction"] as const;

export const getDeleteInvestmentTransactionMutationOptions = <
  TError = ErrorType<ProblemDetails>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof deleteInvestmentTransaction>>,
    TError,
    DeleteInvestmentTransactionMutationVariables,
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof deleteInvestmentTransaction>>,
  TError,
  DeleteInvestmentTransactionMutationVariables,
  TContext
> => {
  const mutationKey = getDeleteInvestmentTransactionMutationKey();
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && "mutationKey" in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof deleteInvestmentTransaction>>,
    DeleteInvestmentTransactionMutationVariables
  > = (props) => {
    const { id } = props ?? {};

    return deleteInvestmentTransaction(id, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

